// source: understanding.go

/**
 * Shapes for the right half of P2 (backlog 1.2). Cases and roles are
 * proposed by the principal and confirmed or corrected by the human;
 * nothing here blocks the work (fichas §2).
 */
export interface CaseView {
  label: string;
  text: string;
  counts?: boolean;
  criterion_label?: string;
  state: string;
}
export interface UnderstandingView {
  /**
   * Status is how the last understanding turn ended (P-43): "none"
   * (none ended yet), "accepted", or "agent_pending" (it failed twice
   * and stays pending for the agent), read from the events so a
   * reload still shows it.
   */
  status: string;
  understood: string;
  cases: CaseView[];
  sections: SectionRoleView[];
  /**
   * EvidenceRequired is nil until the «Entendí» proposes it (B-51).
   */
  evidence_required?: EvidenceRequiredView;
  /**
   * PlanConfirmed: you answered the plan, confirming or correcting it
   * (R-6, plan_confirmed).
   */
  plan_confirmed: boolean;
}
export interface SectionRoleView {
  label: string;
  title: string;
  role: string;
  role_state: string;
  /**
   * Focus is what the section concludes or addresses: the section's
   * own once it has one (yours, or the plan's line after you answered
   * it), else the plan's proposed line; EvidenceFrom is where its
   * evidence will come from, from the plan (R-6, B-53).
   */
  focus?: string;
  evidence_from?: string;
}
export interface CorrectCaseRequest {
  text: string;
}
export interface PutRoleRequest {
  role: string;
  /**
   * Plan: the mark is changed from the «Entendí»'s card, so it also
   * answers the plan (R-6).
   */
  plan?: boolean;
}
